-- Kandado uses UUIDv7 for every ID, generated by the database with uuidv7(),
-- which PostgreSQL has built in from version 18. Fail here, with a clear
-- message, rather than in a later migration with an obscure one.
DO $$
BEGIN
    IF current_setting('server_version_num')::int < 180000 THEN
        RAISE EXCEPTION 'Kandado needs PostgreSQL 18 or later; this is %', current_setting('server_version');
    END IF;
END
$$;
